import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';


export type HeartbeatAnimationProps = Record<string, any>;

const GlowPath: React.FC<{
  d: string;
  stroke: string;
  whiteStroke: string;
  baseWidth: number;
  alpha: number;
}> = ({ d, stroke, whiteStroke, baseWidth, alpha }) => {
  if (!d) return null;
  return (
    <g style={{ transition: "none" }}>
      <path
        d={d}
        fill="none"
        stroke={stroke}
        strokeWidth={baseWidth * 6}
        opacity={0.15 * alpha}
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ transition: "none" }}
      />
      <path
        d={d}
        fill="none"
        stroke={stroke}
        strokeWidth={baseWidth * 3}
        opacity={0.4 * alpha}
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ transition: "none" }}
      />
      <path
        d={d}
        fill="none"
        stroke={stroke}
        strokeWidth={baseWidth}
        opacity={1.0 * alpha}
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ transition: "none" }}
      />
      <path
        d={d}
        fill="none"
        stroke={whiteStroke}
        strokeWidth={baseWidth * 0.3}
        opacity={0.9 * alpha}
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ transition: "none" }}
      />
    </g>
  );
};

const HeartbeatAnimation: React.FC<HeartbeatAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  lineColor = "#ff000f",
  lineWidth = 4,
  sweeps = 3,
  tailLengthPct = 40,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;
  const durationInFrames = durationInSeconds * fps;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Geometry for the heartbeat spike
  const P1 = width * 0.2;
  const P2 = width * 0.23;
  const P3 = width * 0.28;
  const P4 = width * 0.31;
  const cy = height / 2;
  
  // Scale spikes relative to the shortest edge so they fit gracefully on any canvas
  const spikeUp = Math.min(width, height) * 0.3;
  const spikeDown = Math.min(width, height) * 0.3;

  const getY = (x: number, isHeartbeat: boolean) => {
    if (!isHeartbeat) return cy;
    if (x <= P1) return cy;
    if (x <= P2) return interpolate(x, [P1, P2], [cy, cy - spikeUp]);
    if (x <= P3) return interpolate(x, [P2, P3], [cy - spikeUp, cy + spikeDown]);
    if (x <= P4) return interpolate(x, [P3, P4], [cy + spikeDown, cy]);
    return cy;
  };

  const getPath = (startX: number, endX: number, isHeartbeat: boolean) => {
    if (startX >= endX) return "";
    let d = `M ${startX} ${getY(startX, isHeartbeat)} `;
    
    // Add internal points if the segment spans across the heartbeat spike
    if (isHeartbeat) {
      const points = [P1, P2, P3, P4];
      for (const p of points) {
        if (p > startX && p < endX) {
          d += `L ${p} ${getY(p, isHeartbeat)} `;
        }
      }
    }
    
    d += `L ${endX} ${getY(endX, isHeartbeat)}`;
    return d;
  };

  // EKG Sweep Logic
  const totalX = interpolate(frame, [0, durationInFrames], [0, sweeps * width]);
  const currentX = totalX % width;
  const tailLength = width * (tailLengthPct / 100);

  // Calculate active overlapping sweep segments to ensure seamless wrap-around
  const startSweep = Math.floor((totalX - tailLength) / width);
  const endSweep = Math.floor(totalX / width);

  const segments: Array<{
    s: number;
    x0: number;
    x1: number;
    t0: number;
    t1: number;
    path: string;
  }> = [];

  for (let sweepIndex = startSweep; sweepIndex <= endSweep; sweepIndex++) {
    if (sweepIndex < 0) continue; // Don't draw wrap-around before the animation starts

    const u0 = Math.max(totalX - tailLength, sweepIndex * width);
    const u1 = Math.min(totalX, (sweepIndex + 1) * width);

    if (u0 >= u1) continue;

    const x0 = u0 - sweepIndex * width;
    const x1 = u1 - sweepIndex * width;

    const t0 = (u0 - (totalX - tailLength)) / tailLength;
    const t1 = (u1 - (totalX - tailLength)) / tailLength;

    // Drawing heartbeat spike only on the first sweep index (index 0) for realistic continuous EKG
    const isHeartbeat = sweepIndex === 0;
    const path = getPath(x0, x1, isHeartbeat);

    segments.push({
      s: sweepIndex,
      x0,
      x1,
      t0,
      t1,
      path,
    });
  }

  const baseWidth = lineWidth * s;
  const dotX = currentX;
  const currentSweep = Math.floor(totalX / width);
  const dotY = getY(currentX, currentSweep === 0);

  const showDot = frame < durationInFrames;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          overflow: "visible",
          transition: "none",
        }}
      >
        <defs>
          {segments.map((seg) => (
            <React.Fragment key={seg.s}>
              <linearGradient
                id={`tail-gradient-${seg.s}`}
                x1={seg.x0}
                y1={0}
                x2={seg.x1}
                y2={0}
                gradientUnits="userSpaceOnUse"
              >
                <stop offset="0%" stopColor={lineColor} stopOpacity={seg.t0} />
                <stop offset="100%" stopColor={lineColor} stopOpacity={seg.t1} />
              </linearGradient>
              <linearGradient
                id={`white-tail-gradient-${seg.s}`}
                x1={seg.x0}
                y1={0}
                x2={seg.x1}
                y2={0}
                gradientUnits="userSpaceOnUse"
              >
                <stop offset="0%" stopColor="#ffffff" stopOpacity={seg.t0} />
                <stop offset="100%" stopColor="#ffffff" stopOpacity={seg.t1} />
              </linearGradient>
            </React.Fragment>
          ))}
        </defs>

        {segments.map((seg) => (
          <GlowPath
            key={seg.s}
            d={seg.path}
            stroke={`url(#tail-gradient-${seg.s})`}
            whiteStroke={`url(#white-tail-gradient-${seg.s})`}
            baseWidth={baseWidth}
            alpha={1}
          />
        ))}
        
        {showDot && (
          <g style={{ transition: "none" }}>
            <circle
              cx={dotX}
              cy={dotY}
              r={baseWidth * 4}
              fill={lineColor}
              opacity={0.2}
              style={{ transition: "none" }}
            />
            <circle
              cx={dotX}
              cy={dotY}
              r={baseWidth * 2}
              fill={lineColor}
              opacity={0.6}
              style={{ transition: "none" }}
            />
            <circle
              cx={dotX}
              cy={dotY}
              r={baseWidth * 0.8}
              fill="#ffffff"
              opacity={1}
              style={{ transition: "none" }}
            />
          </g>
        )}
      </svg>
    </AbsoluteFill>
  );
};

export default HeartbeatAnimation;